class Solution { public String smallestSubsequence(String s){int[] remaining=new int[26];boolean[] used=new boolean[26];for(char ch:s.toCharArray())remaining[ch-'a']++;StringBuilder stack=new StringBuilder();for(char ch:s.toCharArray()){int index=ch-'a';remaining[index]--;if(used[index])continue;while(stack.length()>0&&stack.charAt(stack.length()-1)>ch&&remaining[stack.charAt(stack.length()-1)-'a']>0){used[stack.charAt(stack.length()-1)-'a']=false;stack.deleteCharAt(stack.length()-1);}stack.append(ch);used[index]=true;}return stack.toString();} }
